// Triage & Paramedic Unit Assignment Engine
const payload = $input.first().json.body || $input.first().json;

const confidence = payload.triage?.fused_confidence || 0.90;
const location = payload.location || { sector: '(0,0)', simulated_lat: 12.9716, simulated_lon: 77.5946 };
const victimName = payload.triage?.victim_name || 'SURVIVOR';
const readings = payload.sensor_corroboration || {};

// Calculate Triage Tier
let priority = 'CODE RED (CRITICAL)';
let etaMinutes = 4.5;
if (confidence >= 0.85) {
  priority = 'CODE RED (IMMEDIATE EXTRACTION)';
  etaMinutes = 3.8;
} else if (confidence >= 0.70) {
  priority = 'CODE YELLOW (STABILIZE & SECURE)';
  etaMinutes = 6.2;
} else {
  priority = 'CODE GREEN (MONITOR)';
  etaMinutes = 10.0;
}

// Generate Emergency Dispatch Card
const alertCard = `🚨 *EMERGENCY SAR DISPATCH — PROTOPLASM SWARM*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
  `🎯 *Victim:* ${victimName}\n` +
  `📍 *Sector:* ${location.sector} (Lat: ${location.simulated_lat}, Lon: ${location.simulated_lon})\n` +
  `🩺 *Triage Tier:* ${priority}\n` +
  `🧠 *Fused AI Confidence:* ${(confidence * 100).toFixed(1)}%\n` +
  `📊 *Sensors:* YOLO Vision: ${(readings.yolo_vision * 100).toFixed(0)}% | Audio: ${(readings.yamnet_acoustic * 100).toFixed(0)}% | Thermal: ${(readings.passive_thermal * 100).toFixed(0)}%\n` +
  `🚑 *Assigned Ground Unit:* Mobile Rescue Unit ALPHA-01 (ETA: ${etaMinutes} mins)\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`;

return [{
  json: {
    incident_id: payload.incident_id || `SAR-${Date.now()}`,
    status: 'PARAMEDIC_DISPATCHED',
    assigned_unit: 'MOBILE_RESCUE_ALPHA_01',
    eta_minutes: etaMinutes,
    triage_tier: priority,
    alert_message: alertCard,
    coordinates: location
  }
}];
